if(HERO_ART_DUPLICATES.length)throw Error('角色立绘资源索引重复：'+HERO_ART_DUPLICATES.join(','));
if(Object.keys(REMAINING_ART_ID).length!==27||new Set(Object.values(REMAINING_ART_ID)).size!==27)throw Error('剩余神将画面映射非法');
