function portrait(h,cls=''){const idx=HERO_ART_BY_ID[h.id];if(HEROS[h.id]!==h)throw Error('神将身份与立绘索引不一致：'+h.id);
 const special=SPECIAL_ART_ID[h.id];
 if(Number.isInteger(special))return `<span class="portrait art atlas-special ${cls}" data-hero-id="${h.id}" data-art-index="special-${special}" role="img" aria-label="${h.name}专属立绘" style="--art-x:${(special%3)*50}%;--art-y:${Math.floor(special/3)*50}%"><span class="portrait-corner">${h.camp.slice(0,1)} · ${h.role.slice(0,1)}</span></span>`;

 const original=REMAINING_ART_ID[h.id];
 if(Number.isInteger(original))return `<span class="portrait art atlas-remaining-v94 ${cls}" data-hero-id="${h.id}" data-art-index="remaining-${original}" role="img" aria-label="${h.name}角色立绘" style="--art-x:${(original%9)*(100/8)}%;--art-y:${Math.floor(original/9)*50}%"><span class="portrait-corner">${h.camp.slice(0,1)} · ${h.role.slice(0,1)}</span></span>`;
 if(Number.isInteger(idx))return `<span class="portrait art ${cls} atlas-${Math.floor(idx/36)}" data-hero-id="${h.id}" data-art-index="${idx}" role="img" aria-label="${h.name}立绘" style="--art-x:${idx%6*20}%;--art-y:${Math.floor((idx%36)/6)*20}%"><span class="portrait-corner">${h.camp.slice(0,1)} · ${h.role.slice(0,1)}</span></span>`;
 throw Error('立绘资源未分配：'+h.name);
}
