function starRealm(star){const value=Math.max(0,Math.min(30,Number(star)||0));return {stage:value?Math.min(5,Math.floor((value-1)/5)):0,filled:value?((value-1)%5)+1:0,value}}
function starPlate(star,style='small'){
 const v=starRealm(star),r=STAR_REALMS[v.stage],finish=style==='board';
 const stars=(filled,base)=>Array.from({length:5},(_,i)=>`<span class="star-slot ${i<filled?'lit':''}" aria-hidden="true">★</span>`).join('');
 if(finish)return `<section class="ascension-panel" style="--realm-color:${r.color};--realm-glow:${r.glow}"><div class="ascension-head"><div><small>HEAVENLY ASCENSION · 六境三十星</small><h3>${r.name}境 <span>${r.title}</span></h3></div><strong>${v.value}/30</strong></div><div class="current-five">${stars(v.filled)}</div><p class="star-progression-note">每境五颗星 · 突破自动强化攻击、生命和先手 · 境界效果已计入战斗属性</p><div class="realm-roadmap">${STAR_REALMS.map((q,i)=>{let n=i<v.stage?5:i===v.stage?v.filled:0;return `<div class="realm-step ${i===v.stage?'current':''} ${i<v.stage?'done':''}" style="--realm-color:${q.color};--realm-glow:${q.glow}"><div class="realm-label"><b>${q.name}</b><small>${i*5+1}—${i*5+5}星</small></div><div class="realm-five">${stars(n)}</div></div>`}).join('')}</div></section>`;
 return `<span class="star-plate ${style}" style="--realm-color:${r.color};--realm-glow:${r.glow}" role="img" aria-label="${r.name}境，${v.value}星"><span class="star-plate-row">${stars(v.filled)}</span><span class="star-realm-name">${r.name}</span></span>`;
}
