const BOND_NAMES=new Set(HEROS.map(h=>h.name));
if(BOND_RULES.some(x=>x.members.some(name=>!BOND_NAMES.has(name))))throw Error('角色羁绊包含不存在的神将');
function bondsFor(h){return BOND_RULES.filter(rule=>rule.members.includes(h.name))}
function activeBonds(lineup){const members=new Set(lineup.map(id=>HEROS[id]?.name).filter(Boolean));return BOND_RULES.filter(x=>x.members.every(n=>members.has(n)))}
