function bondEffectDesc(effect){return ({strike:'对敌人追加伤害',execute:'专攻残血目标',shield:'全队获得护盾',guard:'前排获得护盾与反震',heal:'回复气血并净化',energy:'为队友快速充能',burn:'叠加灼烧并引爆',shock:'雷击与感电',control:'控制与削弱',drain:'吸血追击',sleep:'令敌人昏睡',poison:'持续中毒',chain:'随机连续追击',mark:'施加易伤',regen:'持续恢复',freeze:'冰封敌人'})[effect]||'全队连携'}
