function banner(){return BANNERS.find(b=>b.id===activeBanner)||BANNERS[0]}
function ensurePoolState(){
 if(!S.bannerPity||typeof S.bannerPity!=='object')S.bannerPity={};
 for(const b of BANNERS){const p=S.bannerPity[b.id]||{};S.bannerPity[b.id]={rare:Math.max(0,Math.min(29,Number(p.rare??(b.id==='standard'?S.pity:0))||0)),myth:Math.max(0,Math.min(79,Number(p.myth??(b.id==='standard'?S.mythPity:0))||0))};}
 if(!S.relicFragments||typeof S.relicFragments!=='object')S.relicFragments={};
 if(!Array.isArray(S.summonHistory))S.summonHistory=[];if(!Number.isFinite(S.echoes)||S.echoes<0)S.echoes=0;
}
function bannerPity(){ensurePoolState();return S.bannerPity[activeBanner]}
