function renderRoster(){let tabs=['全部','神话','传说','史诗','灵品','已拥有','天庭','道门','上古','佛门','妖族','冥府','人间'];let ids=HEROS.filter(h=>filter==='全部'||filter===h.tier||filter===h.camp||(filter==='已拥有'&&S.units[h.id])).sort((a,b)=>Number(!!S.units[b.id])-Number(!!S.units[a.id])||['神话','传说','史诗','灵品'].indexOf(a.tier)-['神话','传说','史诗','灵品'].indexOf(b.tier)||a.id-b.id).map(h=>h.id);return `<div class="section"><h2>万神图鉴</h2><small>${Object.keys(S.units).length}/${HEROS.length} 位已拥有</small></div><div class="filters">${tabs.map(t=>`<button class="filter ${filter===t?'on':''}" data-act="filter" data-value="${t}">${t}</button>`).join('')}</div><div class="roster-meta"><span>✦ ${filter} · 共 ${ids.length} 位</span><span>已拥有优先 · 点击查看详情</span></div><div class="grid roster">${ids.map(card).join('')}</div><p class="footnote">点击角色查看神通、法宝与命魂技能树。每位神将可以培养至30星。</p>`}
function renderTeam(){let count=S.lineup.length,p=teamCombatPower(S.lineup),aura=beastAura();return `<div class="section"><h2>五方神阵</h2>${pill(`${count}/5 位已上阵`)}</div><div class="paper panel"><div class="mini-title" style="margin-top:0">当前阵容 · 前二后三</div><div class="team-train-hint">点任意神将头像，即可升1级 / 连升5级 / 升星 / 穿戴装备；操作后保持在当前英雄。</div><div class="lineup">${Array.from({length:5},(_,i)=>{let id=S.lineup[i];return id!==undefined?`<button class="slot" data-act="detail" data-id="${id}">${smallPortrait(HEROS[id])}<div class="name">${HEROS[id].name}</div><div class="tiny">${starPlate(S.units[id].star,'lineup')}</div></button>`:`<div class="slot">➕<br><small>空位</small></div>`}).join('')}</div><div class="statrow"><div class="stat"><strong>${nfmt(p)}</strong><small>综合战力估算</small></div><div class="stat"><strong>${count}/5</strong><small>上阵人数</small></div><div class="stat"><strong>${S.beastLine.filter(v=>v!==null).length}/2</strong><small>异兽助阵</small></div></div><div class="beast-aura-line">异兽永久加成：攻击 +${Math.round(aura.atk*1000)/10}% · 气血 +${Math.round(aura.hp*1000)/10}% · 先手 +${aura.speed} ｜ 已计入综合战力</div><div class="actions">${btn('羁绊智能布阵','autoTeam','ghost')}${btn('进入仙魔战场','goBattle','primary')}</div></div><div class="section"><h2>替换神将</h2><small>点按神仙选择上阵 / 下阵</small></div><div class="grid">${Object.keys(S.units).map(Number).sort((a,b)=>power(b)-power(a)).map(card).join('')}</div><div class="section"><h2>同行异兽</h2></div><div class="hscroll">${S.beastLine.map(id=>id===null?'<div class="beast" style="min-width:140px">空缺异兽位</div>':`<div class="beast active" style="min-width:140px">${beastArt(id,"beast-deployed")}<div class="name">${BEASTS[id].name}</div><div class="tiny">Lv.${S.beasts[id].level} · ${BEASTS[id].skill}</div></div>`).join('')}</div>${btn('前往仙府管理异兽','goBeast','ghost')}${`<div class="active-path">✧ 当前道统：${(teamPaths().find(p=>p.id===S.path&&p.count>=3)||{}).name||'尚未激活（需3位契合神仙）'}</div>`}${heroComboPanel(S.lineup)}${renderBondSection(S.lineup)}${renderPaths()}`}
function freshBattle(){if(S.storyMode==='expedition')return expeditionFreshBattle();let rank=(S.storyMode==='tower'?S.tower+3:S.stage);let list=Array.from({length:5},(_,i)=>{let ids=HEROS.filter(h=>h.tier!=='神话');return ids[(rank*7+i*11)%ids.length].id});let good=S.lineup.map((id,i)=>fighter(id,false,i,rank));let enemy=list.map((id,i)=>fighter(id,true,i,rank));if(rank%5===0&&enemy[0])enemy[0].status['护盾值']=(enemy[0].status['护盾值']||0)+Math.round(enemy[0].max*.22);let path=PATHS.find(p=>p.id===S.path&&p.members.filter(n=>S.lineup.some(id=>HEROS[id].name===n)).length>=3);
const bonds=activeBonds(S.lineup),heroCombos=heroCombosFor(S.lineup);return{round:0,good,enemy,bonds,heroCombos,comboCooldown:{},comboStats:{},comboVisuals:[],comboRound:0,bondRoundUsed:{},path:path?.id||null,pathCharge:0,focus:0,commands:2,precast:[],over:false,win:false,log:[`已激活 ${bonds.length} 组神缘羁绊 · 羁绊神通会自动触发`,`第 ${rank} 关 · ${rank%5===0?'魔尊试炼':'万妖来袭'}！`]}}
function fighter(id,enemy,i,stage){const h=HEROS[id],stats=battleStats(id,S.lineup,i,enemy,stage);
 const u=enemy?null:S.units[id],asc=u?breakthroughBonus(u.star):{energy:0};
 return{id,name:h.name,icon:h.icon,role:h.role,skill:h.skill,kind:h.kind,fx:h.fx,passive:h.passive,
 max:stats.hp,hp:stats.hp,atk:stats.atk,speed:stats.speed,
 energy:40+(i%2?12:0)+(h.passive==='先机'?35:0)+(asc.energy||0),
 status:h.passive==='钟魂'?{'护盾值':Math.floor(stats.atk*2)}:{},enemy,slot:i,revived:false};}
function renderFighter(f){let ratio=clamp(f.hp/f.max*100,0,100);return `<div class="fighter ${f.hp<=0?'dead':''} ${f.enemy?'enemy':''}">${smallPortrait(HEROS[f.id])}<div class="name">${f.name}</div><div class="hp"><span style="width:${ratio}%"></span></div><div class="status">先手 ${f.speed} · ${Object.keys(f.status).filter(k=>f.status[k]>0).slice(0,2).join(' ')}</div></div>`}

