function autoGear(){const u=S.units[selected];if(!u)return;
 const occupied=new Set(Object.keys(S.units).filter(key=>Number(key)!==selected).flatMap(key=>S.units[key].gear).filter(id=>id!==null));
 const candidates=TYPES.map((_,slot)=>[null,...S.gear.filter(g=>g.slot===slot&&!occupied.has(g.id)).sort((a,b)=>gearScore(b)-gearScore(a)).slice(0,7)]);
 let best=-Infinity,winners=null;
 for(const a of candidates[0])for(const b of candidates[1])for(const c of candidates[2])for(const d of candidates[3]){
  const items=[a,b,c,d],set=setSummaryForGear(items);let score=items.reduce((sum,g)=>sum+(g?gearScore(g):0),0);
  score+=set.atk*820+set.hp*470+set.speed*10;
  score+=set.active4.length*330;score+=set.active2.length*45;
  if(score>best){best=score;winners=items}
 }
 if(winners){u.gear=winners.map(g=>g?g.id:null);msg(`神阵配装完成 · ${winners.filter(Boolean).length}/4部位 · 激活${setSummaryForGear(winners).active4.length}项四件套效果`)}
 render();
}
