function equip(id){let g=S.gear.find(g=>g.id===id);if(!g||!S.units[selected])return;for(let key in S.units)S.units[key].gear=S.units[key].gear.map(slot=>slot===id?null:slot);S.units[selected].gear[g.slot]=id;modal=gearReturnHero?'hero':'';if(gearReturnHero)heroTab='装备';msg('已穿戴 '+gearName(g)+' · '+gearEffectLabel(g));render()}
